import sys

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def createTree(parent, N):
    if N == 0:
        return None

    # Dictionary to store node objects by their value
    nodes = [None] * N
    # Dictionary to track children added for each parent
    # We use a list to store children in order of appearance
    children_map = {}

    root = None

    for i in range(N):
        p = parent[i]
        nodes[i] = Node(i)

        if p == -1:
            root = nodes[i]
        else:
            if p not in children_map:
                children_map[p] = []
            children_map[p].append(nodes[i])

    # Assign left and right children based on order of appearance
    for p in children_map:
        children = children_map[p]
        if len(children) >= 1:
            nodes[p].left = children[0]
        if len(children) >= 2:
            nodes[p].right = children[1]

    return root

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    try:
        N = int(next(iterator))
        parent = []
        for _ in range(N):
            parent.append(int(next(iterator)))
    except StopIteration:
        return

    root = createTree(parent, N)

    # Perform level order traversal to output the result
    if not root:
        return

    result = []
    queue = [root]

    while queue:
        node = queue.pop(0)
        result.append(str(node.val))
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)

    print(" ".join(result))

if __name__ == "__main__":
    main()
